 "content": "def transform(grid):
    """Complete the aligned marker rows/columns inside their bounding box."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != background]
    if not points:
        return [row[:] for row in grid]

    rmin = min(r for r, c in points)
    rmax = max(r for r, c in points)
    cmin = min(c for r, c in points)
    cmax = max(c for r, c in points)
    row_lines = {r for r in range(rmin, rmax + 1)
                 if sum(grid[r][c] != background for c in range(cmin, cmax + 1)) >= 2}
    col_lines = {c for c in range(cmin, cmax + 1)
                 if sum(grid[r][c] != background for r in range(rmin, rmax + 1)) >= 2}

    out = [row[:] for row in grid]
    for r in range(rmin, rmax + 1):
        for c in range(cmin, cmax + 1):
            if (r in row_lines or c in col_lines) and grid[r][c] == background:
                out[r][c] = 2
    return out

if __name__ == '__main__':
    demo = [[5] * 17 for _ in range(21)]
    for r, c in [(3,3),(3,13),(6,0),(9,0),(9,1),(9,3),(9,5),(9,7),(9,10),(9,11),(9,13),(11,0),(11,3),(11,7),(11,13)]:
        demo[r][c] = 0
    expected = [[5] * 17 for _ in range(21)]
    for c in range(14):
        if c not in (3, 13): expected[3][c] = 2
    for r in range(3, 12):
        if r not in (3, 6, 9, 11): expected[r][0] = 2
        if r not in (3, 9, 11): expected[r][13] = 2
    for c in range(14):
        if c not in (0, 1, 3, 5, 7, 10, 11, 13): expected[9][c] = 2
        if c not in (0, 3, 7, 13): expected[11][c] = 2
    for r, c in [(3,3),(3,13),(6,0),(9,0),(9,1),(9,3),(9,5),(9,7),(9,10),(9,11),(9,13),(11,0),(11,3),(11,7),(11,13)]:
        expected[r][c] = 0
    assert transform(demo) == expected, 'demo pair mismatch'
    print('demo pair: PASS')

    test = [[1] * 23 for _ in range(29)]
    for c in list(range(10, 19)) + [20, 21]: test[13][c] = 3
    for r in range(14, 23): test[r][10] = 3; test[r][21] = 3
    for r in [14, 16, 17]: test[r][13] = 3
    for c in range(10, 22): test[23][c] = 3
    result = transform(test)
    assert len(result) == 29 and all(len(row) == 23 for row in result)
    print('test dimensions:', len(result), 'x', len(result[0]))
    for row in result[13:24]: print(' '.join(map(str, row)))
    print('TEST_GRID=' + repr(result))
    print('program test: PASS')
    ",
 "cross_profile": false
}

