    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != background]
    if not points:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)

    # Repeated columns form vertical strokes; only those with at least three
    # original markers are treated as such (isolated alignments can belong to
    # the horizontal strokes instead).
    col_counts = {c: sum(grid[r][c] != background for r in range(h)) for c in range(w)}
    vertical_cols = {c for c, n in col_counts.items() if n >= 3}
    out = [row[:] for row in grid]
    for c in vertical_cols:
        for r in range(r0, r1 + 1):
            if grid[r][c] == background:
                out[r][c] = 2

    # Complete horizontal strokes when the row contains markers beyond the
    # already-identified vertical strokes.
    for r in range(r0, r1 + 1):
        marked_cols = {c for c in range(w) if grid[r][c] != background}
        if len(marked_cols) >= 2 and any(c not in vertical_cols for c in marked_cols):
            for c in range(c0, c1 + 1):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out

if __name__ == '__main__':
    # Demo 1
    d1 = [[5] * 17 for _ in range(21)]
    p1 = [(3,3),(3,13),(6,0),(9,0),(9,1),(9,3),(9,5),(9,7),(9,10),(9,11),(9,13),(11,0),(11,3),(11,7),(11,13)]
    for r,c in p1: d1[r][c] = 0
    e1 = [[5] * 17 for _ in range(21)]
    for r,c in p1: e1[r][c] = 0
    for r in (3,9,11):
        for c in range(14):
            if e1[r][c] == 5: e1[r][c] = 2
    for r in range(3,12):
        for c in (0,13):
            if e1[r][c] == 5: e1[r][c] = 2
    assert transform(d1) == e1, 'demo 1 mismatch'

    # Demo 2
    d2 = [[3] * 16 for _ in range(17)]
    p2 = {8:[3,4,5,7,8], 9:[3,8], 10:[3,8], 11:[3,8], 12:[3,4,6,7], 13:[3,8], 14:[3,4,5,6,7,8]}
    for r, cols in p2.items():
        for c in cols: d2[r][c] = 5
    e2 = [row[:] for row in d2]
    for r,c in ((8,6),(12,5),(12,8)): e2[r][c] = 2
    assert transform(d2) == e2, 'demo 2 mismatch'

    # Test grid as supplied in the instance.
    t = [[1] * 23 for _ in range(29)]
    for c in list(range(10,19)) + [20,21]: t[13][c] = 3
    for r in range(14,23): t[r][10] = t[r][21] = 3
    for r in (14,16,17): t[r][13] = 3
    for c in range(10,22): t[23][c] = 3
    ans = transform(t)
    assert len(ans) == 29 and all(len(row) == 23 for row in ans)
    print('Both demos pass; test output:')
    print(ans)
    ",
 "cross_profile": false
}

