    """Draw the missing cells in the broken horizontal strokes of the frame."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != background]
    if not points:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    out = [row[:] for row in grid]

    # A horizontal bar has markers strictly between its left/right frame
    # edges. Fill across those edges; leave vertical-only segments untouched.
    for r in range(r0, r1 + 1):
        if any(grid[r][c] != background for c in range(c0 + 1, c1)):
            for c in range(c0, c1 + 1):
                if grid[r][c] == background:
                    out[r][c] = 2

    # Connect the repeated outer vertical rails. A lone marker at an extreme
    # column (as in demo 3) is an isolated defect, not a rail.
    for c in (c0, c1):
        if sum(grid[r][c] != background for r in range(h)) >= 2:
            for r in range(r0, r1 + 1):
                if grid[r][c] == background:
