    out = [row[:] for row in grid]

    # A horizontal bar has markers strictly between its left/right frame
    # edges. Fill across those edges; leave vertical-only segments untouched.
    for r in range(r0, r1 + 1):
        if any(grid[r][c] != background for c in range(c0 + 1, c1)):
