    # at an interior row with at least four marker cells (a clear stroke).
    for r in range(r0, r1 + 1):
        n_markers = sum(grid[r][c] != background for c in range(w))
        if r in (r0, r1) or n_markers >= 4:
            for c in range(c0, c1 + 1):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out

