    background = max(freq, key=freq.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != background]
    if not points:
        return [row[:] for row in grid]

    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)
    out = [row[:] for row in grid]

    # Complete the bounding frame.
    horizontal_rows = {r0, r1}
    for c in range(c0, c1 + 1):
        if grid[r0][c] == background:
            out[r0][c] = 2
        if grid[r1][c] == background:
            out[r1][c] = 2
    for r in range(r0, r1 + 1):
        if grid[r][c0] == background:
            out[r][c0] = 2
        if grid[r][c1] == background:
            out[r][c1] = 2

    # Interior horizontal strokes are identified by at least two interior
    # markers on the same row, then completed between the frame's sides.
    for r in range(r0 + 1, r1):
        interior = [c for c in range(c0 + 1, c1) if grid[r][c] != background]
        if len(interior) >= 2:
            horizontal_rows.add(r)
            for c in range(c0, c1 + 1):
                if grid[r][c] == background:
                    out[r][c] = 2

    # Complete interior vertical strokes when repeated marks align in a
    # column and are not part of detected horizontal strokes.
    for c in range(c0 + 1, c1):
        rows = [r for r in range(r0 + 1, r1) if grid[r][c] != background]
        if len(rows) >= 2 and not any(r in horizontal_rows for r in rows):
            for r in range(min(rows), max(rows) + 1):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out


